1	#!/usr/bin/env python3
2	"""ClientBook HTTP service."""
3	import argparse
4	import datetime
5	import json
6	import re
7	import signal
8	import sqlite3
9	from http.server import BaseHTTPRequestHandler, HTTPServer
10	from pathlib import Path
11	from urllib.parse import urlsplit
12	
13	PRODUCT = "ClientBook"
14	RESOURCE = "clients"
15	OPTIONAL_FIELDS = ("source", "region", "industry", "important_date")
16	ALL_COLUMNS = ("name",) + OPTIONAL_FIELDS
17	MAX_BODY = 10 * 1024 * 1024
18	DATE_RE = re.compile(r"^(\d{4})-(\d{2})-(\d{2})$")
19	
20	PAGE = '''<!doctype html>
21	<html lang="zh-CN">
22	<head>
23	<meta charset="utf-8">
24	<meta name="viewport" content="width=device-width,initial-scale=1">
25	<title>ClientBook · 客户联系人与商机记录</title>
26	<style>
27	body{font-family:system-ui,sans-serif;max-width:60rem;margin:3rem auto;padding:0 1rem;line-height:1.7;color:#1c2733}
28	a{color:#175b9c}
29	h1{margin-bottom:.2rem}
30	.subtitle{color:#5b6b7b;margin-top:0}
31	.card{border:1px solid #d8dee6;border-radius:8px;padding:1rem 1.25rem;margin:1.5rem 0}
32	.card h2{margin-top:0;font-size:1.15rem}
33	.filename{margin-left:.5rem;color:#5b6b7b}
34	button{font-size:1rem;padding:.45rem 1.4rem;border-radius:6px;border:1px solid #175b9c;background:#175b9c;color:#fff;cursor:pointer}
35	button:disabled{background:#9db6cc;border-color:#9db6cc;cursor:default}
36	.hint{color:#5b6b7b;font-size:.9rem;margin:.35rem 0 0}
37	#report{display:none;margin-top:1rem}
38	.banner{padding:.6rem 1rem;border-radius:6px;margin-bottom:.75rem}
39	.banner.ok{background:#e9f7ec;border:1px solid #bfe3c8}
40	.banner.bad{background:#fdeeee;border:1px solid #f3c4c4}
41	.banner.warn{background:#fdf6e6;border:1px solid #ecd9a8}
42	.banner.busy{background:#eef4fb;border:1px solid #c3d5e8}
43	.failures{border:1px solid #ecd7d7;background:#fdf6f6;border-radius:6px;padding:.5rem 1rem;max-height:16rem;overflow:auto}
44	.failures b{color:#a02b2b}
45	.failures ul{margin:.4rem 0}
46	table{border-collapse:collapse;width:100%}
47	#clients-table{display:none}
48	#clients-table.on{display:table}
49	#clients-empty{display:none}
50	#clients-empty.on{display:block}
51	#clients-load-error{display:none}
52	#clients-load-error.on{display:block;color:#a06a16}
53	th,td{text-align:left;padding:.45rem .6rem;border-bottom:1px solid #e3e8ee;vertical-align:top}
54	th{font-size:.85rem;color:#5b6b7b;font-weight:600}
55	.muted{color:#9aa7b4}
56	#clients-body tr.selected{background:#f1f6fb}
57	.sel-panel{background:#f5f8fb;border:1px solid #d8dee6;border-radius:6px;padding:.6rem .8rem;margin:.8rem 0}
58	.sel-list{margin-top:.35rem}
59	.sel-chip{display:inline-block;background:#fff;border:1px solid #cdd7e2;border-radius:999px;padding:.1rem .35rem .1rem .6rem;margin:.2rem .35rem .2rem 0;font-size:.9rem;white-space:nowrap}
60	.sel-chip button{border:none;background:none;color:#5b6b7b;font-size:1.05rem;line-height:1;padding:0 .25rem;cursor:pointer}
61	.sel-chip button:hover{color:#a02b2b}
62	.bf{border:1px solid #d8dee6;border-radius:6px;padding:.55rem .8rem;margin:.6rem 0}
63	.bf-head{display:flex;flex-wrap:wrap;gap:.8rem;align-items:center;margin-bottom:.35rem}
64	.bf-head b{min-width:4.5rem}
65	.bf-head label{font-weight:400;white-space:nowrap}
66	.bf textarea{width:100%;box-sizing:border-box;font:inherit;resize:vertical;padding:.3rem .45rem}
67	.bf input[type=text]{font:inherit;padding:.3rem .45rem}
68	.bf textarea:disabled,.bf input:disabled{background:#f2f4f7;color:#8a97a5}
69	.bf .val-hint{margin:.25rem 0 0;font-size:.85rem;color:#5b6b7b}
70	#batch-report{margin-top:.75rem}
71	.footer{color:#5b6b7b;font-size:.9rem;margin-top:2rem}
72	</style>
73	</head>
74	<body>
75	<main>
76	<h1>ClientBook</h1>
77	<p class="subtitle">客户联系人与商机记录</p>
78	
79	<section class="card">
80	<h2>从 CSV 导入客户</h2>
81	<form id="import-form">
82	  <input type="file" id="file-input" accept=".csv,text/csv,text/plain" required>
83	  <span class="filename" id="filename"></span>
84	  <div style="margin-top:.75rem"><button type="submit" id="submit-btn">导入</button></div>
85	</form>
86	<p class="hint">表头须包含 name（必需），可选 source、region、industry、important_date，顺序不限；重要日期须为 YYYY-MM-DD 真实日期。支持带引号字段与字段内换行（UTF-8，可带 BOM）。</p>
87	<div id="report"></div>
88	</section>
89	
90	<h2>客户列表</h2>
91	<p id="clients-empty" class="muted">还没有客户记录。</p>
92	<p id="clients-load-error" class="muted"></p>
93	<table id="clients-table">
94	  <thead><tr><th style="width:2.2rem"><input type="checkbox" id="check-all" title="全选/取消全选当前列表"></th><th>编号</th><th>客户名称</th><th>来源</th><th>地区</th><th>行业</th><th>重要日期</th></tr></thead>
95	  <tbody id="clients-body"></tbody>
96	</table>
97	
98	<section class="card" id="batch-card">
99	<h2>批量修改选中客户</h2>
100	<div class="sel-panel">
101	  已选择 <b id="sel-count">0</b> 名客户：
102	  <div class="sel-list" id="sel-list"><span class="muted" id="sel-none">尚未勾选任何客户，勾选列表中的客户后可批量修改。</span></div>
103	</div>
104	<form id="batch-form">
105	  <div id="batch-fields"></div>
106	  <p class="hint">每个字段可分别选择「保持原值」「设为填写的值」或「清空」；初次进入编辑时全部保持原值，留空不会清空资料。来源、地区和行业保留内部空白与换行，仅含空白的填写值按清空处理；重要日期须为 YYYY-MM-DD 真实日历日期。客户名称和编号不参与编辑，也不会新建客户。</p>
107	  <div style="margin-top:.6rem">
108	    <button type="submit" id="batch-submit" disabled>保存修改</button>
109	  </div>
110	</form>
111	<div id="batch-report"></div>
112	</section>
113	
114	<p class="footer"><a href="/api/clients">查看客户列表接口</a> · <a href="/health">服务状态</a></p>
115	</main>
116	<script>
117	const ESC = {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"};
118	const esc = s => String(s === null || s === undefined ? "" : s).replace(/[&<>"']/g, c => ESC[c]);
119	const blank = v => (v === null || v === undefined || v === "") ? '<span class="muted">—</span>' : esc(v);
120	
121	const BATCH_FIELDS = [
122	  {key: "source", label: "来源"},
123	  {key: "region", label: "地区"},
124	  {key: "industry", label: "行业"},
125	  {key: "important_date", label: "重要日期", date: true},
126	];
127	
128	let clients = [];
129	const selected = new Set();
130	// 一次批量保存从发出到本次结果处理结束期间为 true：期间只能有这一次请求，
131	// 勾选变化与表单重复提交都不能解除或新增请求。
132	let batchSaving = false;
133	
134	function syncSubmitState() {
135	  const btn = document.getElementById("batch-submit");
136	  btn.disabled = batchSaving || selected.size === 0;
137	  btn.textContent = batchSaving ? "正在保存…" : "保存修改";
138	}
139	
140	async function loadClients() {
141	  // 只在明确读到有效客户列表（真正的空列表也算）时才更新页面；
142	  // 连接错误、非成功状态、响应无法解析或未包含 clients 数组都视为读取失败：
143	  // 保留此前已显示的客户编号、名称与各字段内容，不清空表格、不显示空列表提示。
144	  const note = document.getElementById("clients-load-error");
145	  let list;
146	  try {
147	    const res = await fetch("/api/clients");
148	    if (!res.ok) throw new Error("服务返回非成功状态（HTTP " + res.status + "）");
149	    const data = await res.json();
150	    if (!data || !Array.isArray(data.clients)) {
151	      throw new Error("响应未包含有效的客户列表");
152	    }
153	    list = data.clients;
154	  } catch (err) {
155	    let message = err.message;
156	    if (err instanceof SyntaxError) message = "响应无法解析为有效数据";
157	    if (err instanceof TypeError) message = "无法连接到服务（网络错误）";
158	    note.textContent = "客户列表读取失败：" + message +
159	      "，当前显示的资料可能不是最新内容；保存结果不受影响，稍后刷新页面即可重新读取。";
160	    note.classList.add("on");
161	    // 读取失败期间不能让表格或“还没有客户记录”冒充真实的空列表；
162	    // 此前已渲染的行保留不动，之后真正读到空列表时再由 renderClients 恢复空状态提示。
163	    document.getElementById("clients-empty").classList.remove("on");
164	    throw new Error(message);
165	  }
166	  note.classList.remove("on");
167	  note.textContent = "";
168	  clients = list;
169	  const known = new Set(clients.map(r => r.id));
170	  for (const id of [...selected]) {
171	    if (!known.has(id)) selected.delete(id);
172	  }
173	  renderClients();
174	  renderSelection();
175	}
176	
177	function renderClients() {
178	  const tbl = document.getElementById("clients-table");
179	  const empty = document.getElementById("clients-empty");
180	  const body = document.getElementById("clients-body");
181	  if (clients.length) {
182	    tbl.classList.add("on");
183	    empty.classList.remove("on");
184	    body.innerHTML = clients.map(r =>
185	      '<tr data-id="' + esc(r.id) + '"' + (selected.has(r.id) ? ' class="selected"' : "") + ">" +
186	      '<td><input type="checkbox" class="row-check" value="' + esc(r.id) + '"' +
187	      (selected.has(r.id) ? " checked" : "") + " aria-label='选择客户 " + esc(r.id) + "'></td>" +
188	      "<td>" + esc(r.id) + "</td><td>" + esc(r.name) + "</td><td>" + blank(r.source) +
189	      "</td><td>" + blank(r.region) + "</td><td>" + blank(r.industry) +
190	      "</td><td>" + blank(r.important_date) + "</td></tr>").join("");
191	  } else {
192	    tbl.classList.remove("on");
193	    empty.classList.add("on");
194	    body.innerHTML = "";
195	  }
196	  syncCheckAll();
197	}
198	
199	function syncCheckAll() {
200	  const box = document.getElementById("check-all");
201	  box.checked = clients.length > 0 && selected.size === clients.length;
202	  box.indeterminate = selected.size > 0 && selected.size < clients.length;
203	}
204	
205	function renderSelection() {
206	  document.getElementById("sel-count").textContent = String(selected.size);
207	  const list = document.getElementById("sel-list");
208	  if (!selected.size) {
209	    list.innerHTML = '<span class="muted">尚未勾选任何客户，勾选列表中的客户后可批量修改。</span>';
210	  } else {
211	    const byId = new Map(clients.map(r => [r.id, r]));
212	    list.innerHTML = [...selected].sort((a, b) => a - b).map(id => {
213	      const r = byId.get(id);
214	      return '<span class="sel-chip">#' + esc(id) + " " + esc(r ? r.name : "") +
215	        ' <button type="button" data-remove="' + esc(id) + '" title="取消勾选该客户">×</button></span>';
216	    }).join("");
217	  }
218	  syncSubmitState();
219	  document.querySelectorAll("#clients-body tr").forEach(tr => {
220	    tr.classList.toggle("selected", selected.has(Number(tr.dataset.id)));
221	  });
222	  syncCheckAll();
223	}
224	
225	function buildBatchFields() {
226	  const wrap = document.getElementById("batch-fields");
227	  wrap.innerHTML = BATCH_FIELDS.map(f =>
228	    '<div class="bf" data-field="' + f.key + '">' +
229	      '<div class="bf-head"><b>' + f.label + "</b>" +
230	        '<label><input type="radio" name="' + f.key + '-op" value="keep" checked> 保持原值</label>' +
231	        '<label><input type="radio" name="' + f.key + '-op" value="set"> 设为填写的值</label>' +
232	        '<label><input type="radio" name="' + f.key + '-op" value="clear"> 清空</label>' +
233	      "</div>" +
234	      (f.date
235	        ? '<input type="text" class="bf-value" disabled placeholder="YYYY-MM-DD" autocomplete="off">'
236	        : '<textarea class="bf-value" rows="2" disabled></textarea>') +
237	      '<p class="val-hint">' + (f.date
238	        ? "非空时须为 YYYY-MM-DD 真实日历日期；仅含空白的填写值按清空处理。"
239	        : "去除前后空白后保存，内部空白与换行保留；仅含空白的填写值按清空处理。") +
240	      "</p></div>").join("");
241	  wrap.querySelectorAll(".bf").forEach(card => {
242	    const input = card.querySelector(".bf-value");
243	    card.querySelectorAll('input[type=radio]').forEach(radio => radio.addEventListener("change", () => {
244	      const op = card.querySelector('input[type=radio]:checked').value;
245	      input.disabled = op !== "set";
246	      if (op === "set") input.focus();
247	    }));
248	  });
249	}
250	
251	function collectBatchPayload() {
252	  const updates = {};
253	  for (const card of document.querySelectorAll("#batch-fields .bf")) {
254	    const key = card.dataset.field;
255	    const op = card.querySelector('input[type=radio]:checked').value;
256	    if (op === "keep") {
257	      updates[key] = {op: "keep"};
258	    } else if (op === "clear") {
259	      updates[key] = {op: "clear"};
260	    } else {
261	      updates[key] = {op: "set", value: card.querySelector(".bf-value").value};
262	    }
263	  }
264	  return {ids: [...selected].sort((a, b) => a - b), updates};
265	}
266	
267	function resetBatchForm() {
268	  document.querySelectorAll("#batch-fields .bf").forEach(card => {
269	    card.querySelector('input[value=keep]').checked = true;
270	    const input = card.querySelector(".bf-value");
271	    input.value = "";
272	    input.disabled = true;
273	  });
274	}
275	
276	function showBatchReport(html) {
277	  document.getElementById("batch-report").innerHTML = html;
278	}
279	
280	document.getElementById("check-all").addEventListener("change", e => {
281	  if (e.target.checked) clients.forEach(r => selected.add(r.id));
282	  else selected.clear();
283	  renderClients();
284	  renderSelection();
285	});
286	
287	document.getElementById("clients-body").addEventListener("change", e => {
288	  if (!e.target.classList.contains("row-check")) return;
289	  const id = Number(e.target.value);
290	  if (e.target.checked) selected.add(id);
291	  else selected.delete(id);
292	  renderSelection();
293	});
294	
295	document.getElementById("sel-list").addEventListener("click", e => {
296	  const btn = e.target.closest("[data-remove]");
297	  if (!btn) return;
298	  selected.delete(Number(btn.dataset.remove));
299	  renderClients();
300	  renderSelection();
301	});
302	
303	document.getElementById("batch-form").addEventListener("submit", async e => {
304	  e.preventDefault();
305	  // 等待结果期间再次提交（重复点击、回车等）一律忽略：不增加请求、不提前显示成功、
306	  // 不清除已填内容；等待期间的勾选变化也不会在结果返回后自动补交。
307	  if (batchSaving) return;
308	  if (!selected.size) {
309	    showBatchReport('<div class="banner bad">请先勾选至少一名客户。</div>');
310	    syncSubmitState();
311	    return;
312	  }
313	  // 以本次点击时的勾选与填写为准，固化请求内容；等待期间勾选变化不影响本次请求。
314	  const payload = collectBatchPayload();
315	  batchSaving = true;
316	  syncSubmitState();
317	  showBatchReport('<div class="banner busy">正在保存本次批量修改，请勿重复提交…</div>');
318	  try {
319	    const res = await fetch("/api/clients/batch-update", {
320	      method: "POST",
321	      headers: {"Content-Type": "application/json"},
322	      body: JSON.stringify(payload),
323	    });
324	    // 响应无法读取或无法解析时，尚未收到服务明确的保存结论：不能当作保存成功，
325	    // 也不使用“已保存、仅刷新失败”的说法，保留勾选与填写供用户确认后重新提交。
326	    let data;
327	    try {
328	      data = await res.json();
329	    } catch (parseErr) {
330	      showBatchReport('<div class="banner bad">批量修改请求失败：保存结果无法读取' +
331	        "（HTTP " + res.status + "），本次修改是否生效无法确认，请稍后核对列表后再决定是否重新提交。</div>");
332	      return;
333	    }
334	    if (!res.ok) {
335	      // 服务明确拒绝：显示具体原因，保留当时页面上的勾选、字段操作及填写内容，
336	      // 由用户修正后主动再次保存。
337	      showBatchReport('<div class="banner bad">本次修改已全部拒绝，客户资料保持原样。<br>原因：' +
338	        esc(data.error || "未知错误") + "</div>");
339	      return;
340	    }
341	    // 服务明确返回成功：成功处理数量以保存回复为准，不按旧表格、当前勾选或刷新结果重算。
342	    // 立即清除本次勾选并把字段编辑恢复为保持原值，随后的列表刷新成败都不改变这一结果。
343	    const count = data.updated_count;
344	    if (typeof count !== "number" || !Number.isFinite(count)) {
345	      // 没有明确的成功与处理数量，不能当作保存成功。
346	      showBatchReport('<div class="banner bad">批量修改请求失败：服务未返回有效的处理数量，' +
347	        "本次修改是否生效无法确认，请稍后核对列表后再决定是否重新提交。</div>");
348	      return;
349	    }
350	    resetBatchForm();
351	    selected.clear();
352	    renderClients();
353	    renderSelection();
354	    let refreshed = true;
355	    try {
356	      await loadClients();
357	    } catch (loadErr) {
358	      refreshed = false;
359	      // 刷新失败不自动重交刚才的修改，也不要求用户再次保存；旧表格（含勾选状态）
360	      // 已按保存成功的结果保留/清除，不被读取失败清空。
361	      showBatchReport(
362	        '<div class="banner ok">已成功处理 <b>' + esc(count) +
363	        "</b> 名客户，勾选已清除，字段编辑已恢复为保持原值。</div>" +
364	        '<div class="banner warn">保存后读取客户列表失败（' + esc(loadErr.message) +
365	        "）：列表暂未更新，当前显示的资料可能仍是保存前的内容；客户资料已按上述结果保存，" +
366	        "稍后重新打开或刷新页面即可看到最新资料，无需再次保存。</div>");
367	    }
368	    if (refreshed) {
369	      showBatchReport('<div class="banner ok">已成功处理 <b>' + esc(count) +
370	        "</b> 名客户，列表已更新，勾选已清除，字段编辑已恢复为保持原值。</div>");
371	    }
372	  } catch (err) {
373	    // 请求失败也要结束等待并显示失败，不能使页面一直无法继续使用。
374	    showBatchReport('<div class="banner bad">批量修改请求失败：' + esc(err.message) + "</div>");
375	  } finally {
376	    // 等待结束：是否能保存仍取决于有没有选中客户（成功后已清除勾选）。
377	    batchSaving = false;
378	    syncSubmitState();
379	  }
380	});
381	
382	buildBatchFields();
