555	def _normalize_set_value(field_name, value):
556	    """校验 set 操作的值并返回最终入库值；非法时抛 BatchUpdateError。
557	
558	    去除前后空白；仅含空白按清空（None）处理；来源/地区/行业保留内部空白与换行；
559	    重要日期非空时须为 YYYY-MM-DD 真实日历日期。
560	    """
561	    if not isinstance(value, str):
562	        raise BatchUpdateError("%s的设置值不是文本" % FIELD_LABELS[field_name])
563	    text = value.strip()
564	    if not text:
565	        return None
566	    if field_name == "important_date":
567	        ok, reason = check_date(text)
568	        if not ok:
569	            raise BatchUpdateError(reason)
570	    return text
