573	def batch_update_clients(database, payload):
574	    """执行批量修改，返回 {"updated_count": 去重后的客户数}；非法请求抛 BatchUpdateError。
575	
576	    任一问题都整次拒绝，不写入任何客户。
577	    """
578	    if not isinstance(payload, dict):
579	        raise BatchUpdateError("请求体必须是 JSON 对象")
580	
581	    raw_ids = payload.get("ids")
582	    if not isinstance(raw_ids, list):
583	        raise BatchUpdateError("ids 必须是客户编号数组")
584	    if not raw_ids:
585	        raise BatchUpdateError("未选择客户：请先勾选至少一名客户")
586	
587	    ids = []
588	    seen_ids = set()
589	    for raw_id in raw_ids:
590	        if isinstance(raw_id, bool) or not isinstance(raw_id, int) or raw_id <= 0:
591	            raise BatchUpdateError("客户编号必须是正整数：%r 不合法" % (raw_id,))
592	        if raw_id not in seen_ids:
593	            seen_ids.add(raw_id)
594	            ids.append(raw_id)
595	
596	    raw_updates = payload.get("updates", {})
597	    if not isinstance(raw_updates, dict):
598	        raise BatchUpdateError("updates 必须是字段修改说明对象")
599	    extra = [key for key in raw_updates if key not in OPTIONAL_FIELDS]
600	    if extra:
601	        raise BatchUpdateError("包含不能修改或不存在的字段：%s" % "、".join(extra))
602	
603	    actions = {}
604	    for field_name in OPTIONAL_FIELDS:
605	        spec = raw_updates.get(field_name, {"op": "keep"})
606	        if not isinstance(spec, dict):
607	            raise BatchUpdateError("%s的修改说明必须是对象" % FIELD_LABELS[field_name])
608	        op = spec.get("op")
609	        if op not in ("keep", "set", "clear"):
610	            raise BatchUpdateError(
611	                "%s的操作必须是 keep、set 或 clear 之一" % FIELD_LABELS[field_name])
612	        if op == "keep":
613	            continue
614	        if op == "clear":
615	            actions[field_name] = None
616	        else:
617	            actions[field_name] = _normalize_set_value(field_name, spec.get("value"))
618	
619	    if not actions:
620	        raise BatchUpdateError("全部字段均保持原值：请至少选择一个字段进行设置或清空")
621	
622	    placeholders = ",".join("?" for _ in ids)
623	    existing = {
624	        row[0]
625	        for row in database.execute(
626	            "SELECT id FROM clients WHERE id IN (%s)" % placeholders, ids
627	        )
628	    }
629	    missing = [cid for cid in ids if cid not in existing]
630	    if missing:
631	        raise BatchUpdateError("找不到对应客户，编号：%s" % "、".join(str(c) for c in missing))
632	
633	    assignments = ", ".join("%s = ?" % field_name for field_name in actions)
634	    params = list(actions.values()) + ids
635	    try:
636	        database.execute(
637	            "UPDATE clients SET %s WHERE id IN (%s)" % (assignments, placeholders), params
638	        )
639	        database.commit()
640	    except sqlite3.DatabaseError:
641	        database.rollback()
642	        raise BatchUpdateError("保存失败：数据库错误，本次修改未生效")
643	
644	    return {"updated_count": len(ids)}
