647	def parse_csv(text):
648	    """解析 RFC 4180 风格 CSV，返回 (header, data_rows)。
649	
650	    支持引号包裹的字段、引号内逗号与换行、双引号转义；
651	    引号外支持 LF / CRLF / CR 换行。结构损坏时抛 FileError：
652	    - 未加引号的字段中出现双引号（双引号只能在字段开头用于包住整个字段）；
653	    - 结束引号后出现逗号、换行或文件结束以外的字符（含空格）；
654	    - 文件结束时仍有字段处于引号内（引号未闭合）。
655	    错误信息区分上述三种情况，并指出发生在表头还是第 N 条数据记录
656	    （数据记录编号不包含表头，引号字段内的换行不增加编号）。
657	    """
658	    rows = []
659	    record = []
660	    field = []
661	    quoted = False        # 当前字段处于引号内
662	    started = False       # 当前字段已经开始（已有内容或已进入引号）
663	    closed = False       # 引号字段刚结束，等待逗号 / 换行 / 文件结束
664	    record_number = 0     # 0 = 表头，1 起为数据记录
665	    i = 0
666	    n = len(text)
667	
668	    def location():
669	        return "表头" if record_number == 0 else "第 %d 条数据记录" % record_number
670	
671	    def structure_error(kind):
672	        raise FileError("CSV 结构损坏（%s）：%s" % (location(), kind))
673	
674	    def finish_record():
675	        nonlocal record, field, started, closed
676	        record.append("".join(field))
677	        rows.append(record)
678	        record = []
679	        field = []
680	        started = False
681	        closed = False
682	
683	    while i < n:
684	        c = text[i]
685	        if quoted:
686	            if c == '"':
687	                if i + 1 < n and text[i + 1] == '"':
688	                    field.append('"')
689	                    i += 2
690	                    continue
691	                quoted = False
692	                closed = True
693	                i += 1
694	                continue
695	            if c == "\r":
696	                # 统一字段内换行符为 LF
697	                if i + 1 < n and text[i + 1] == "\n":
698	                    i += 1
699	                field.append("\n")
700	                i += 1
701	                continue
702	            field.append(c)
703	            i += 1
704	            continue
705	        if closed:
706	            # 引号已结束，只允许逗号、记录换行或文件结束
707	            if c == ",":
708	                record.append("".join(field))
709	                field = []
710	                started = False
711	                closed = False
712	            elif c in "\r\n":
713	                if c == "\r" and i + 1 < n and text[i + 1] == "\n":
714	                    i += 1
715	                finish_record()
716	                record_number += 1
717	            else:
718	                structure_error("结束引号后有多余字符，结束引号后只能紧接逗号、记录换行或文件结束")
719	            i += 1
720	            continue
721	        if c == '"' and not started:
722	            quoted = True
723	            started = True
724	        elif c == '"':
725	            structure_error("未加引号的字段中出现双引号，双引号只能在字段开头用于包住整个字段")
726	        elif c == ",":
727	            record.append("".join(field))
728	            field = []
729	            started = False
730	        elif c in "\r\n":
731	            if c == "\r" and i + 1 < n and text[i + 1] == "\n":
732	                i += 1
733	            if not started and not record and not field:
734	                # 空白行：不作为数据记录（显式的 "" 空字段 started=True，仍会保留）
735	                i += 1
736	                continue
737	            finish_record()
738	            record_number += 1
739	        else:
740	            field.append(c)
741	            started = True
742	        i += 1
743	    if quoted:
744	        structure_error("引号未闭合，文件结束时仍有字段处于引号内")
745	    if started or field or record or closed:
746	        record.append("".join(field))
747	        rows.append(record)
748	    if not rows:
749	        raise FileError("CSV 内容为空：缺少表头")
750	    return rows[0], rows[1:]
