753	def check_date(value):
754	    """校验 YYYY-MM-DD 且为真实日历日期，返回 (是否合法, 错误原因)。"""
755	    match = DATE_RE.match(value)
756	    if not match:
757	        return False, "重要日期格式无效（%s）：须为 YYYY-MM-DD" % value
758	    try:
759	        datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
760	    except ValueError:
761	        return False, "重要日期无效（%s）：不是真实日历日期" % value
762	    return True, None
