765	def import_clients(database, text):
766	    """执行导入，返回响应字典；文件级错误抛 FileError。"""
767	    header, data_rows = parse_csv(text)
768	    headers = [h.strip() for h in header]
769	
770	    seen = set()
771	    duplicates = []
772	    for h in headers:
773	        if h in seen and h not in duplicates:
774	            duplicates.append(h)
775	        seen.add(h)
776	    if duplicates:
777	        raise FileError("表头重复：%s" % "、".join(repr(h) for h in duplicates))
778	    unknown = [h for h in headers if h not in ALL_COLUMNS]
779	    if unknown:
780	        raise FileError("出现未知列：%s" % "、".join(repr(h) for h in unknown))
781	    if "name" not in headers:
782	        raise FileError("缺少名称列：表头必须包含 name 列")
783	
784	    index = {h: i for i, h in enumerate(headers)}
785	    name_index = index["name"]
786	    date_index = index.get("important_date")
787	
788	    existing = {}
789	    for cid, cname in database.execute("SELECT id, name FROM clients"):
790	        existing[(cname or "").strip().casefold()] = cid
791	
792	    imported = []
793	    failures = []
794	    seen_in_file = {}
795	
796	    for row_number, raw in enumerate(data_rows, start=1):
797	        if len(raw) != len(headers):
798	            failures.append({
799	                "row": row_number,
800	                "reason": "列数不符：表头有 %d 列，该记录有 %d 列" % (len(headers), len(raw)),
801	            })
802	            continue
803	
804	        name = raw[name_index].strip()
805	        problems = []
806	        if not name:
807	            problems.append("缺少名称：name 列为空")
808	        date_value = ""
809	        if date_index is not None:
810	            date_value = raw[date_index].strip()
811	            if date_value:
812	                ok, reason = check_date(date_value)
813	                if not ok:
814	                    problems.append(reason)
815	        if problems:
816	            failures.append({"row": row_number, "reason": "；".join(problems)})
817	            continue
818	
819	        key = name.casefold()
820	        if key in existing:
821	            failures.append({
822	                "row": row_number,
823	                "reason": "名称与已有客户重复（已有客户编号 %d），未更新" % existing[key],
824	            })
825	            continue
826	        if key in seen_in_file:
827	            failures.append({
828	                "row": row_number,
829	                "reason": "名称与文件内第 %d 条记录重复" % seen_in_file[key],
830	            })
831	            continue
832	
833	        seen_in_file[key] = row_number
834	        record = {"name": name}
835	        for field_name in OPTIONAL_FIELDS:
836	            idx = index.get(field_name)
837	            value = raw[idx].strip() if idx is not None else ""
838	            record[field_name] = value or None
839	        imported.append((row_number, record))
840	
841	    saved = []
842	    for row_number, record in imported:
843	        cursor = database.execute(
844	            "INSERT INTO clients (name, source, region, industry, important_date)"
845	            " VALUES (:name, :source, :region, :industry, :important_date)",
846	            record,
847	        )
848	        saved.append({"row": row_number, "id": cursor.lastrowid, "name": record["name"]})
849	    database.commit()
850	
851	    return {
852	        "imported_count": len(saved),
853	        "failed_count": len(failures),
854	        "imported": saved,
855	        "failures": failures,
856	    }
