859	def main():
860	    parser = argparse.ArgumentParser(description="ClientBook - 客户联系人与商机记录")
861	    commands = parser.add_subparsers(dest="command", required=True)
862	    serve = commands.add_parser("serve", help="Start the HTTP service")
863	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
864	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
865	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
866	    args = parser.parse_args()
