123	async function openSession(browser, base) {
124	  const page = await browser.newPage();
125	  const modes = {
126	    // ok 正常转发；close 连接断开；500 非成功状态；bad-json 无法解析；
127	    // no-clients 可解析但缺少客户数组
128	    list: "ok",
129	    // batch 响应改写：null = 走真实后端；否则用给定 {status, body}
130	    batchOverride: null,
131	    // batchHold 为 true 时挂起保存请求（既不应答也不转发），模拟服务尚未给出结果
132	    batchHold: false,
133	  };
134	  const counts = {batchPosts: 0, listGets: 0};
135	  // 被挂起的保存请求：{request, payload}，放行时 continue 发往真实后端
136	  const held = [];
137	
138	  await page.setRequestInterception(true);
139	  page.on("request", request => {
140	    const url = request.url();
141	    if (request.method() === "GET" && url.endsWith("/api/clients")) {
142	      counts.listGets += 1;
143	      if (modes.list === "close") { request.abort("failed"); return; }
144	      if (modes.list === "500") {
145	        request.respond({status: 500, contentType: "application/json; charset=utf-8",
146	          body: JSON.stringify({error: "模拟的服务错误"})});
147	        return;
148	      }
149	      if (modes.list === "bad-json") {
150	        request.respond({status: 200, contentType: "application/json; charset=utf-8",
151	          body: "<<<not valid json>>>"});
152	        return;
153	      }
154	      if (modes.list === "no-clients") {
155	        request.respond({status: 200, contentType: "application/json; charset=utf-8",
156	          body: JSON.stringify({unexpected: true})});
157	        return;
158	      }
159	      request.continue();
160	      return;
161	    }
162	    if (request.method() === "POST" && url.endsWith("/api/clients/batch-update")) {
163	      counts.batchPosts += 1;
164	      if (modes.batchHold) {
165	        held.push({request, payload: request.postData()});
166	        return;
167	      }
168	      if (modes.batchOverride) {
169	        const {status, body} = modes.batchOverride;
170	        request.respond({status, contentType: "application/json; charset=utf-8", body});
171	        return;
172	      }
173	    }
174	    request.continue();
175	  });
176	
177	  await page.setCacheEnabled(false);
178	  await page.goto(base + "/", {waitUntil: "networkidle0"});
179	  return {page, modes, counts, held};
180	}
