        {a: realNow.clients.find(x => x.id === a).industry,
         b: realNow.clients.find(x => x.id === b).industry});

      // ===================================================================
      // 场景 D：读取失败后不重发（直接计数）；重新打开页面读取成功即恢复
      // ===================================================================
      {
        const session = await openSession(browser, base);
