          `posts=${session.counts.batchPosts}`);
        check("D 失败当次：旧表仍显示保存前来源，勾选与编辑已清理、按钮禁用",
          snap.rows.find(r => r.id === String(a)).cells[1] === "页面新来源" &&
          snap.rows.find(r => r.id === String(c)).cells[1] === "广告" &&
